/**
 * 共有APIクライアントファクトリ
 *
 * Web（Nuxt）とCLI（Bun）の両方から利用される、
 * Nusk APIへのリクエストを抽象化した中核モジュール。
 * fetcher関数を注入することで、環境に依存しないAPIクライアントを生成する。
 */
import type { List, Status, Task, StatusCategory } from '../index'

/** HTTPリクエストの共通オプション型 */
interface FetchOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE'
  body?: Record<string, unknown> | null
  query?: Record<string, string | undefined>
}

/** 汎用フェッチ関数の型エイリアス（Nuxtの$fetchやBunのfetchなどを受け取る） */
type Fetcher = <T = unknown>(url: string, options?: FetchOptions) => Promise<T>

/**
 * APIクライアントを生成するファクトリ関数
 *
 * 各リソース（lists, statuses, tasks, setup）に対するCRUD操作メソッドを返す。
 * @param fetcher - 環境固有のHTTPクライアント関数（Nuxtでは$fetch、CLIではfetchなど）
 * @returns リソースごとのAPI操作メソッドを持つオブジェクト
 */
export function createApiClient(fetcher: Fetcher) {
  return {
    // --- リスト（Lists）操作 ---
    lists: {
      /** 全リストを取得 */
      getAll: () =>
        fetcher<List[]>('/api/v1/lists'),

      /** 新規リストを作成 */
      create: (body: { name: string; is_inbox?: boolean; sort_order?: number }) =>
        fetcher<List>('/api/v1/lists', { method: 'POST', body }),

      /** リストを部分更新 */
      update: (id: string, body: { name?: string; sort_order?: number; is_inbox?: boolean }) =>
        fetcher<List>(`/api/v1/lists/${id}`, { method: 'PATCH', body }),

      /** リストを削除 */
      delete: (id: string) =>
        fetcher<null>(`/api/v1/lists/${id}`, { method: 'DELETE' }),
    },

    // --- ステータス（Statuses）操作 ---
    statuses: {
      /** 全ステータスを取得（リストIDで絞り込み可能） */
      getAll: (query?: { list_id?: string }) =>
        fetcher<Status[]>('/api/v1/statuses', { query }),

      /** 新規ステータスを作成 */
      create: (body: {
        name: string
        category?: StatusCategory
        color?: string
        sort_order?: number
        list_id?: string | null
      }) =>
        fetcher<Status>('/api/v1/statuses', { method: 'POST', body }),

      /** ステータスを部分更新 */
      update: (id: string, body: {
        name?: string
        category?: StatusCategory
        color?: string
        sort_order?: number
        list_id?: string | null
      }) =>
        fetcher<Status>(`/api/v1/statuses/${id}`, { method: 'PATCH', body }),

      /** ステータスを削除 */
      delete: (id: string) =>
        fetcher<null>(`/api/v1/statuses/${id}`, { method: 'DELETE' }),
    },

    // --- タスク（Tasks）操作 ---
    tasks: {
      /** 全タスクを取得（リストID・着手予定日・ステータスIDで絞り込み可能） */
      getAll: (query?: { list_id?: string; scheduled_date?: string; status_id?: string }) =>
        fetcher<Task[]>('/api/v1/tasks', { query }),

      /** 指定IDのタスクを1件取得 */
      get: (id: string) =>
        fetcher<Task>(`/api/v1/tasks/${id}`),

      /** 新規タスクを作成 */
      create: (body: {
        title: string
        list_id?: string
        status_id?: string
        scheduled_date?: string | null
      }) =>
        fetcher<Task>('/api/v1/tasks', { method: 'POST', body }),

      /** タスクを部分更新（ステータス変更、リスト移動、リスケジュール、論理削除などに対応） */
      update: (id: string, body: {
        title?: string
        status_id?: string
        list_id?: string
        scheduled_date?: string | null
        sort_order?: number
        deleted_at?: string | null
      }) =>
        fetcher<Task>(`/api/v1/tasks/${id}`, { method: 'PATCH', body }),
    },

    // --- 初期セットアップ操作 ---
    setup: {
      /** デフォルトのリストとステータスを一括作成する初期化API */
      init: (body: {
        lists?: Array<{ name: string; is_inbox: boolean }>
        statuses?: Array<{ name: string; category: StatusCategory; color: string }>
      }) =>
        fetcher<unknown>('/api/v1/setup/init', { method: 'POST', body }),
    },
  }
}

/** createApiClientの戻り値から推論されるAPIクライアントの型（外部での型参照用） */
export type ApiClient = ReturnType<typeof createApiClient>

/**
 * Nuxt用APIクライアント composable
 *
 * Nuxtが提供する$fetch（ofetch）をcreateApiClientに注入し、
 * SSR/CSR両対応のAPIクライアントインスタンスを返す。
 * コンポーネントや他のcomposableからAPI呼び出しを行う際のエントリーポイント。
 */
import { createApiClient } from '@nusk/shared'

/** Nuxtの$fetchを使ったAPIクライアントを生成して返す */
export const useApi = () => createApiClient($fetch)

/**
 * タスク管理メインストア composable
 *
 * リスト・ステータス・タスクのグローバル状態を管理し、
 * データ取得・タスク追加・スケジュール変更・完了トグルなどの
 * アクション関数を提供する。useStateによるSSR対応のシングルトンストア。
 */
import type { List, Status, Task } from '@nusk/shared'

/** Date オブジェクトを "YYYY-MM-DD" 形式の文字列に変換するユーティリティ */
const toDateStr = (d: Date) =>
  `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`

export const useTaskStore = () => {
  const api = useApi()

  // --- グローバルステート（useStateでSSR/CSR間で共有） ---
  const lists = useState<List[]>('task-lists', () => [])
  const statuses = useState<Status[]>('task-statuses', () => [])
  const tasks = useState<Task[]>('task-items', () => [])

  /** データ取得中フラグ */
  const loading = useState('task-loading', () => false)
  /** 初回データ取得完了フラグ（二重ロード防止に使用） */
  const loaded = useState('task-loaded', () => false)

  /** 現在選択中のリストID */
  const selectedListId = useState<string>('selected-list-id', () => '')
  /** 表示モード: "list"（リスト別） or "date"（日付別） */
  const viewMode = useState<'list' | 'date'>('view-mode', () => 'list')

  // --- 算出プロパティ（派生データ） ---

  /** 現在選択中のリストオブジェクト */
  const selectedList = computed(() =>
    lists.value.find(l => l.id === selectedListId.value),
  )

  /** 選択中リストに属するタスク一覧 */
  const filteredTasks = computed(() =>
    tasks.value.filter(t => t.list_id === selectedListId.value),
  )

  // --- ユーティリティ関数 ---

  /** ステータスIDからステータスオブジェクトを検索 */
  const getStatus = (statusId: string) =>
    statuses.value.find(s => s.id === statusId)

  /** 指定リストに属するタスク数を返す */
  const taskCount = (listId: string) =>
    tasks.value.filter(t => t.list_id === listId).length

  /** 今日の日付文字列（"YYYY-MM-DD"） */
  const todayStr = computed(() => toDateStr(new Date()))

  /** 明日の日付文字列（"YYYY-MM-DD"） */
  const tomorrowStr = computed(() => {
    const d = new Date()
    d.setDate(d.getDate() + 1)
    return toDateStr(d)
  })

  /** 着手予定日が今日のタスク数 */
  const todayCount = computed(() =>
    tasks.value.filter(t => t.scheduled_date === todayStr.value).length,
  )

  /** 着手予定日が明日のタスク数 */
  const tomorrowCount = computed(() =>
    tasks.value.filter(t => t.scheduled_date === tomorrowStr.value).length,
  )

  /** 指定日付が今日かどうかを判定 */
  const isToday = (date: string | null) => date === todayStr.value

  /** 日付文字列を "M/D" 形式にフォーマット（nullの場合は空文字） */
  const formatDate = (date: string | null) => {
    if (!date) return ''
    const d = new Date(date + 'T00:00:00')
    return `${d.getMonth() + 1}/${d.getDate()}`
  }

  // --- アクション関数（API通信を伴うデータ操作） ---

  /**
   * リスト・ステータス・タスクの初回一括取得
   *
   * 全データをPromise.allで並列取得し、ローカルステートに格納する。
   * 初回ロード済みの場合はスキップ。取得後、Inboxリストを自動選択する。
   */
  async function fetchData() {
    if (loaded.value) return
    loading.value = true
    try {
      const [listsRes, statusesRes, tasksRes] = await Promise.all([
        api.lists.getAll(),
        api.statuses.getAll(),
        api.tasks.getAll(),
      ])
      lists.value = listsRes
      statuses.value = statusesRes
      tasks.value = tasksRes

      // 未選択の場合、Inboxリストをデフォルト選択
      const inbox = lists.value.find(l => l.is_inbox)
      if (inbox && !selectedListId.value) {
        selectedListId.value = inbox.id
      }
      loaded.value = true
    } finally {
      loading.value = false
    }
  }

  /**
   * 現在選択中のリストに新規タスクを追加
   * @param title - タスクのタイトル
   */
  async function addTask(title: string) {
    const task = await api.tasks.create({
      title,
      list_id: selectedListId.value,
    })
    tasks.value.push(task)
  }

  /**
   * タスクの着手予定日（scheduled_date）を変更
   * @param taskId - 対象タスクのID
   * @param date - 新しい着手予定日（"YYYY-MM-DD"形式）
   */
  async function scheduleTask(taskId: string, date: string) {
    const updated = await api.tasks.update(taskId, { scheduled_date: date })
    const index = tasks.value.findIndex(t => t.id === taskId)
    if (index !== -1) tasks.value[index] = updated
  }

  /**
   * タスクの完了/未完了をトグルする
   *
   * 現在のステータスカテゴリがDONEならTODOへ、TODOならDONEへ切り替える。
   * 同じリスト（またはグローバル）に属する対象カテゴリのステータスを自動検索し、
   * そのステータスIDでタスクを更新する。
   * @param taskId - 対象タスクのID
   */
  async function completeTask(taskId: string) {
    const task = tasks.value.find(t => t.id === taskId)
    if (!task) return

    // 現在のステータスカテゴリを判定し、トグル先カテゴリを決定
    const currentStatus = statuses.value.find(s => s.id === task.status_id)
    const targetCategory = currentStatus?.category === 'DONE' ? 'TODO' : 'DONE'
    // 同一リストまたはグローバル（list_id === null）のステータスから対象カテゴリを検索
    const newStatus = statuses.value.find(
      s => (s.list_id === task.list_id || s.list_id === null) && s.category === targetCategory,
    )
    if (!newStatus) return

    const updated = await api.tasks.update(taskId, { status_id: newStatus.id })
    const index = tasks.value.findIndex(t => t.id === taskId)
    if (index !== -1) tasks.value[index] = updated
  }

  return {
    // ステート
    lists,
    statuses,
    tasks,
    loading,
    loaded,
    selectedListId,
    viewMode,
    // 算出プロパティ
    selectedList,
    filteredTasks,
    // ユーティリティ
    getStatus,
    taskCount,
    todayStr,
    tomorrowStr,
    todayCount,
    tomorrowCount,
    isToday,
    formatDate,
    // アクション
    fetchData,
    addTask,
    scheduleTask,
    completeTask,
  }
}

/**
 * APIペイロード・クエリ型定義
 *
 * createApiClient の各メソッドで使用するリクエストボディ・クエリパラメータの型。
 * Web（Nuxt）とCLI（Bun）の両方から共通で参照される。
 */
import type { StatusCategory } from './database'

// --- リスト（Lists） ---

/** リスト作成時のリクエストボディ */
export type CreateListPayload = {
  name: string
  is_inbox?: boolean
  sort_order?: number
}

/** リスト更新時のリクエストボディ（全フィールド任意） */
export type UpdateListPayload = {
  name?: string
  sort_order?: number
  is_inbox?: boolean
}

// --- ステータス（Statuses） ---

/** ステータス一覧取得時のクエリパラメータ */
export type GetStatusesQuery = {
  list_id?: string
}

/** ステータス作成時のリクエストボディ */
export type CreateStatusPayload = {
  name: string
  category?: StatusCategory
  color?: string
  sort_order?: number
  list_id?: string | null
}

/** ステータス更新時のリクエストボディ（全フィールド任意） */
export type UpdateStatusPayload = {
  name?: string
  category?: StatusCategory
  color?: string
  sort_order?: number
  list_id?: string | null
}

// --- タスク（Tasks） ---

/** タスク一覧取得時のクエリパラメータ */
export type GetTasksQuery = {
  list_id?: string
  scheduled_date?: string
  status_id?: string
}

/** タスク作成時のリクエストボディ */
export type CreateTaskPayload = {
  title: string
  list_id?: string
  status_id?: string
  scheduled_date?: string | null
}

/** タスク更新時のリクエストボディ（ステータス変更、リスト移動、リスケジュール、論理削除に対応） */
export type UpdateTaskPayload = {
  title?: string
  status_id?: string
  list_id?: string
  scheduled_date?: string | null
  sort_order?: number
  deleted_at?: string | null
}

// --- 初期セットアップ ---

/** 初期セットアップ時のリクエストボディ（リストとステータスを一括作成） */
export type SetupInitPayload = {
  lists?: Array<{ name: string; is_inbox: boolean }>
  statuses?: Array<{ name: string; category: StatusCategory; color: string }>
}

/**
 * 共有APIクライアントファクトリ
 *
 * Web（Nuxt）とCLI（Bun）の両方から利用される、
 * Nusk APIへのリクエストを抽象化した中核モジュール。
 * fetcher関数を注入することで、環境に依存しないAPIクライアントを生成する。
 */
import type { List, Status, Task } from '../index'
import type {
  CreateListPayload,
  UpdateListPayload,
  GetStatusesQuery,
  CreateStatusPayload,
  UpdateStatusPayload,
  GetTasksQuery,
  CreateTaskPayload,
  UpdateTaskPayload,
  SetupInitPayload,
} from '../types/api'

/** HTTPリクエストの共通オプション型 */
interface FetchOptions {
  method?: 'GET' | 'POST' | 'PATCH' | 'PUT' | 'DELETE'
  body?: Record<string, unknown> | null
  query?: Record<string, string | undefined>
}

/** 汎用フェッチ関数の型エイリアス（Nuxtの$fetchやBunのfetchなどを受け取る） */
type Fetcher = <T = unknown>(url: string, options?: FetchOptions) => Promise<T>

/**
 * APIクライアントを生成するファクトリ関数
 *
 * 各リソース（lists, statuses, tasks, setup）に対するCRUD操作メソッドを返す。
 * @param fetcher - 環境固有のHTTPクライアント関数（Nuxtでは$fetch、CLIではfetchなど）
 * @returns リソースごとのAPI操作メソッドを持つオブジェクト
 */
export function createApiClient(fetcher: Fetcher) {
  return {
    // --- リスト（Lists）操作 ---
    lists: {
      /** 全リストを取得 */
      getAll: () =>
        fetcher<List[]>('/api/v1/lists'),

      /** 新規リストを作成 */
      create: (body: CreateListPayload) =>
        fetcher<List>('/api/v1/lists', { method: 'POST', body }),

      /** リストを部分更新 */
      update: (id: string, body: UpdateListPayload) =>
        fetcher<List>(`/api/v1/lists/${id}`, { method: 'PATCH', body }),

      /** リストを削除 */
      delete: (id: string) =>
        fetcher<null>(`/api/v1/lists/${id}`, { method: 'DELETE' }),
    },

    // --- ステータス（Statuses）操作 ---
    statuses: {
      /** 全ステータスを取得（リストIDで絞り込み可能） */
      getAll: (query?: GetStatusesQuery) =>
        fetcher<Status[]>('/api/v1/statuses', { query }),

      /** 新規ステータスを作成 */
      create: (body: CreateStatusPayload) =>
        fetcher<Status>('/api/v1/statuses', { method: 'POST', body }),

      /** ステータスを部分更新 */
      update: (id: string, body: UpdateStatusPayload) =>
        fetcher<Status>(`/api/v1/statuses/${id}`, { method: 'PATCH', body }),

      /** ステータスを削除 */
      delete: (id: string) =>
        fetcher<null>(`/api/v1/statuses/${id}`, { method: 'DELETE' }),
    },

    // --- タスク（Tasks）操作 ---
    tasks: {
      /** 全タスクを取得（リストID・着手予定日・ステータスIDで絞り込み可能） */
      getAll: (query?: GetTasksQuery) =>
        fetcher<Task[]>('/api/v1/tasks', { query }),

      /** 指定IDのタスクを1件取得 */
      get: (id: string) =>
        fetcher<Task>(`/api/v1/tasks/${id}`),

      /** 新規タスクを作成 */
      create: (body: CreateTaskPayload) =>
        fetcher<Task>('/api/v1/tasks', { method: 'POST', body }),

      /** タスクを部分更新（ステータス変更、リスト移動、リスケジュール、論理削除などに対応） */
      update: (id: string, body: UpdateTaskPayload) =>
        fetcher<Task>(`/api/v1/tasks/${id}`, { method: 'PATCH', body }),
    },

    // --- 初期セットアップ操作 ---
    setup: {
      /** デフォルトのリストとステータスを一括作成する初期化API */
      init: (body: SetupInitPayload) =>
        fetcher<unknown>('/api/v1/setup/init', { method: 'POST', body }),
    },
  }
}

/** createApiClientの戻り値から推論されるAPIクライアントの型（外部での型参照用） */
export type ApiClient = ReturnType<typeof createApiClient>

